require_once __DIR__.'/config/config.php';require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT t.*,s.sezon_adi FROM toylar t LEFT JOIN sezonlar s ON s.id=t.sezon_id WHERE t.id=?');$st->execute([$id]);$toy=$st->fetch();if(!$toy)redirect(BASE_URL.'/toylar.php');$turler=toy_turleri();$kategoriler=toy_kategorileri();$basliklar=toy_puan_basliklari($toy);$st=$pdo->prepare("SELECT s.id,s.ad,s.soyad,COALESCE(SUM(p.puan),0) toplam FROM toy_katilimcilari k JOIN sporcular s ON s.id=k.sporcu_id LEFT JOIN toy_puanlari p ON p.toy_id=k.toy_id AND p.sporcu_id=s.id WHERE k.toy_id=? GROUP BY s.id ORDER BY toplam DESC,s.ad,s.soyad");$st->execute([$id]);$sporcular=$st->fetchAll();$sayfa_baslik=$toy['toy_adi'];$aktif='toylar';require __DIR__.'/includes/header.php';
